state.b++            // 不触发，runs 仍然是 4
state.a++            // 触发 → runs = 5

// 3) 手动清理：把一个 effect 从账本上摘干净（注销、销毁组件时用得上）
const runner = effect(() => { state.a })
cleanupEffect(runner)
state.a++            // 不再触发这个 runner
runner.deps.length   // 0

