/**
 * 第 9 关 · computed：懒计算、缓存、还能被依赖（完整实现）
 *
 * 1) getter 包成 lazy effect：创建时不算
 * 2) _dirty + _value：脏了才重算，不脏给缓存
 * 3) 两层依赖：lazy effect 负责「我读了谁」，track(this, value) 负责「谁读了我」
 */
const targetMap = new WeakMap()
let activeEffect = null
const effectStack = []

function track(target, key) {
  if (!activeEffect) return
  let depsMap = targetMap.get(target)
  if (!depsMap) targetMap.set(target, (depsMap = new Map()))
  let dep = depsMap.get(key)
  if (!dep) depsMap.set(key, (dep = new Set()))
  if (!dep.has(activeEffect)) {
    dep.add(activeEffect)
    if (!activeEffect.deps) activeEffect.deps = []
    activeEffect.deps.push(dep)
  }
}

function cleanupEffect(eff) {
  for (const dep of eff.deps ?? []) dep.delete(eff)
  eff.deps.length = 0
}

function trigger(target, key) {
  const depsMap = targetMap.get(target)
  if (!depsMap) return
  const dep = depsMap.get(key)
  if (!dep) return
  for (const eff of [...dep]) {
    if (eff.scheduler) eff.scheduler(eff)
    else eff()
  }
}

function reactive(target) {
  return new Proxy(target, {
    get(t, key, receiver) {
      track(t, key)
      return Reflect.get(t, key, receiver)
    },
    set(t, key, value, receiver) {
      const old = t[key]
      const ok = Reflect.set(t, key, value, receiver)
      if (ok && !Object.is(old, value)) trigger(t, key)
      return ok
    }
  })
}

function effect(fn, options = {}) {
  const runner = () => {
    cleanupEffect(runner)
    effectStack.push(runner)
    activeEffect = runner
    try {
      return fn()
    } finally {
      effectStack.pop()
      activeEffect = effectStack[effectStack.length - 1] ?? null
    }
  }
  runner.deps = []
  runner.scheduler = options.scheduler
  if (!options.lazy) runner()
  return runner
}

const jobQueue = new Set()

function queueJob(job) {
  jobQueue.add(job)
}

function flushJobs() {
  const jobs = [...jobQueue]
  jobQueue.clear()
  for (const job of jobs) job()
}

class ComputedRefImpl {
  constructor(getter) {
    this._dirty = true
    this._value = undefined
    this.effect = effect(getter, {
      lazy: true,
      scheduler: () => {
        if (!this._dirty) {
          this._dirty = true
          trigger(this, 'value')
        }
      }
    })
  }

  get value() {
    if (this._dirty) {
      this._dirty = false
      this._value = this.effect()
    }
    track(this, 'value')
    return this._value
  }
}

function computed(getter) {
  return new ComputedRefImpl(getter)
}

